import sys
import re
import os

def parse_expression(expr):
    try:
        return eval(expr, {'__builtins__': None}, {})
    except:
        return 0

def render_template(template_path, output_path, assignments):
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    names = {}
    for line in assignments:
        line = line.strip()
        if not line:
            continue
        try:
            name, expr = line.split('=', 1)
            name = name.strip()
            expr = expr.strip()
            value = parse_expression(expr)
            names[name] = value
        except ValueError:
            continue

    def replace_placeholders(match):
        expr = match.group(1).strip()
        return str(parse_expression(expr))

    pattern = re.compile(r'\{\{([^}]+)\}\}')
    rendered = pattern.sub(replace_placeholders, template)

    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(rendered)

    return len(pattern.findall(template))

def main():
    if len(sys.stdin.readlines()) < 2:
        sys.exit(0)

    template_path = sys.stdin.readline().strip()
    output_path = sys.stdin.readline().strip()
    assignments = [line.strip() for line in sys.stdin if line.strip()]

    count = render_template(template_path, output_path, assignments)
    print(count)

if __name__ == '__main__':
    main()

