import sys
import re

def main():
    template_path = sys.stdin.readline().strip()
    output_path = sys.stdin.readline().strip()
    assignments = {}

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, expr = line.split('=', 1)
        assignments[name] = expr

    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    def evaluate(expr):
        stack = []
        i = 0
        n = len(expr)
        while i < n:
            if expr[i] == ' ':
                i += 1
                continue
            if expr[i] == '(':
                stack.append('(')
                i += 1
            elif expr[i] == ')':
                stack.append(')')
                i += 1
            elif expr[i] in '+-*/':
                stack.append(expr[i])
                i += 1
            elif expr[i].isalpha():
                name = expr[i]
                if name in assignments:
                    stack.append(str(assignments[name]))
                else:
                    raise ValueError(f"Undefined variable: {name}")
                i += 1
            else:
                # Handle integer literals
                j = i
                while j < n and expr[j].isdigit():
                    j += 1
                if j > i:
                    stack.append(expr[i:j])
                    i = j
                else:
                    raise ValueError(f"Invalid character in expression: {expr[i]}")
        # Evaluate the stack
        while len(stack) > 1:
            if stack[-2] == '+':
                a = stack.pop()
                b = stack.pop()
                stack.append(str(int(b) + int(a)))
            elif stack[-2] == '-':
                a = stack.pop()
                b = stack.pop()
                stack.append(str(int(b) - int(a)))
            elif stack[-2] == '*':
                a = stack.pop()
                b = stack.pop()
                stack.append(str(int(b) * int(a)))
            elif stack[-2] == '/':
                a = stack.pop()
                b = stack.pop()
                stack.append(str(int(b) // int(a)))
            else:
                raise ValueError("Invalid operator")
            stack.pop()  # Remove the operator
        return stack[0] if stack else '0'

    def replace_placeholders(text):
        def replacer(match):
            expr = match.group(1)
            try:
                return evaluate(expr)
            except ValueError as e:
                raise ValueError(f"Error evaluating expression '{expr}': {e}")
        return re.sub(r'\{\{(.*?)\}\}', replacer, text)

    result = replace_placeholders(template)
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(result)

if __name__ == '__main__':
    main()
